function wbAudit(action,title,detail='',extra={},actor='You'){log(action,{},actor,title,detail,extra);persist();}
function wbTaskProject(t){return t.project||data.features.find(f=>f.id===t.feature)?.project;}
function wbProjectTasks(projectId){return [...data.cards,...data.wb.issues].filter(t=>wbTaskProject(t)===projectId);}
function wbTaskBlockers(t){const tasks=wbProjectTasks(wbTaskProject(t));return (t.deps||[]).filter(id=>{const p=tasks.find(x=>x.id===id);return !p||p.archived||!wbIsComplete(p)||p.acceptanceVerified!==true;});}
function wbTaskDependents(t){return wbProjectTasks(wbTaskProject(t)).filter(x=>(x.deps||[]).includes(t.id));}
function wbValidateTaskDependencies(id,projectId,deps){const tasks=wbProjectTasks(projectId),byId=new Map(tasks.map(t=>[t.id,t])),old=byId.get(id);if(new Set(deps).size!==deps.length)throw Error('Duplicate blocking task.');if(deps.includes(id))throw Error('A task cannot block itself.');for(const dep of deps)if(!byId.has(dep))throw Error('Choose a task in the same project.');if(old&&wbIsComplete(old)&&JSON.stringify(old.deps||[])!==JSON.stringify(deps))throw Error('Reopen completed work before changing its prerequisites.');const active=new Set(),done=new Set();function visit(key){if(active.has(key))throw Error('This dependency would create a cycle.');if(done.has(key))return;active.add(key);for(const dep of key===id?deps:(byId.get(key)?.deps||[]))visit(dep);active.delete(key);done.add(key);}for(const t of tasks)visit(t.id);if(!byId.has(id))visit(id);}
function wbTaskQueueKey(t){return wbTaskProject(t)+':'+(t.feature||'standalone');}
function wbTaskQueueRevision(projectId,featureId=null){data.wb.taskQueueRevisions??={};return data.wb.taskQueueRevisions[projectId+':'+(featureId||'standalone')]||1;}
function wbAdvanceTaskQueue(t){data.wb.taskQueueRevisions??={};const key=wbTaskQueueKey(t);data.wb.taskQueueRevisions[key]=(data.wb.taskQueueRevisions[key]||1)+1;}
function wbPatchProjectTask(id,version,patch,actor='You'){const t=[...data.cards,...data.wb.issues].find(x=>x.id===id);assertVersion(t,version);if(patch.title!==undefined&&!patch.title.trim())throw Error('A task title is required.');if(patch.priority!==undefined&&!priorities.includes(patch.priority))throw Error('Choose a supported priority.');if(patch.deps!==undefined)wbValidateTaskDependencies(id,wbTaskProject(t),patch.deps);const before={priority:t.priority,deps:[...(t.deps||[])]};Object.assign(t,patch);t.version=(t.version||1)+1;if(t.priority!==before.priority||JSON.stringify(t.deps||[])!==JSON.stringify(before.deps))wbAdvanceTaskQueue(t);wbAudit('tasks.edit','Updated '+t.id,JSON.stringify({before,after:{priority:t.priority,deps:t.deps||[]}}),{feature:t.feature,issue:t.feature?undefined:t.id},actor);return t;}
function wbPrioritizeTaskQueue(args,actor='You'){const current=wbTaskQueueRevision(args.projectId,args.featureId);if(current!==args.expectedQueueRevision)throw Error('This task queue changed. Refresh before reordering.');if(!priorities.includes(args.priority)||!args.orderedTaskIds?.length||new Set(args.orderedTaskIds).size!==args.orderedTaskIds.length)throw Error('Choose a priority and unique tasks.');const all=wbProjectTasks(args.projectId),chosen=args.orderedTaskIds.map(id=>all.find(t=>t.id===id));if(chosen.some(t=>!t||t.archived||(t.feature||null)!==(args.featureId||null)))throw Error('Choose tasks in one current project queue.');const queueRecords=args.featureId?all:[...all,...data.features.filter(f=>f.project===args.projectId)];const rest=queueRecords.filter(t=>!t.archived&&(args.featureId?t.feature===args.featureId:!t.feature)&&t.priority===args.priority&&!args.orderedTaskIds.includes(t.id)).sort(wbCompareTaskOrder);for(const [i,t] of [...chosen,...rest].entries()){if(chosen.includes(t))t.priority=args.priority;t.manualOrder=i;t.version=(t.version||1)+1;}wbAdvanceTaskQueue(chosen[0]);wbAudit('tasks.prioritize','Reprioritized tasks',args.orderedTaskIds.join(', '),{},actor);return {revision:current+1,changed:true};}
function wbCompareTaskOrder(a,b){const difference=priorities.indexOf(a.priority)-priorities.indexOf(b.priority);return difference||(a.manualOrder??data.cards.indexOf(a))-(b.manualOrder??data.cards.indexOf(b))||a.id.localeCompare(b.id);}
function wbEligibleTaskPreview(projectId,featureId=null){return wbProjectTasks(projectId).filter(t=>{const f=data.features.find(x=>x.id===t.feature),p=data.projects.find(x=>x.id===projectId);return !p?.archived&&!t.archived&&!t.blocked&&!wbIsComplete(t)&&t.run!=='Paused'&&t.run!=='Working'&&(!f||f.approved&&f.run!=='Paused'&&!(f.budgetEnabled&&f.spent>=f.budgetAmount))&&((featureId&&t.feature===featureId)||(!featureId&&!t.feature))&&!wbTaskBlockers(t).length;}).sort(wbCompareTaskOrder);}
