function wbDependencySummary(t){const tasks=wbProjectTasks(wbTaskProject(t)),ids=wbTaskBlockers(t),dependents=wbTaskDependents(t);return `<div class="wb-note wb-gap"><strong>Blocked by</strong>: ${(t.deps||[]).map(id=>{const p=tasks.find(x=>x.id===id);return (p?wbTaskLink(p):esc(id))+(ids.includes(id)?' (waiting)':' (satisfied)');}).join(', ')||'None'}<br><strong>Blocks</strong>: ${dependents.map(wbTaskLink).join(', ')||'None'}</div>`;}
