function wbApplyConfig(el){const key=el.dataset.config;let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(el.type==='number'&&(!Number.isFinite(value)||value<1||!Number.isInteger(value)&&key!=='budgetAmount'))throw Error('Use a positive value; agent and fix-cycle limits must be whole numbers.');if(key.startsWith('ui:'))ui[key.slice(3)]=value;else if(key.startsWith('tool:'))data.wb.tools[key.slice(5)]=value;else if(key.startsWith('tier:')){data.wb.tierMembership??={};data.wb.tierMembership[key.slice(5)]=value;}else if(key==='systemone:enabled'){data.wb.systemOne??={};data.wb.systemOne.enabled=value;}else if(key.startsWith('model:')){data.wb.models??={};data.wb.models[key.slice(6)]=value;}else if(key.startsWith('skill:'))data.wb.skills.find(x=>x.id===key.slice(6)).enabled=value;else if(key.startsWith('mcp:')){data.wb.mcp??=[{id:'docs',name:'Documentation library',transport:'HTTP',enabled:true},{id:'design',name:'Design assets',transport:'stdio',enabled:false}];data.wb.mcp.find(x=>x.id===key.slice(4)).enabled=value;}else if(key.startsWith('delivery:')){data.wb.delivery[ui.deliveryScope]??={autoMerge:'inherit',mandatoryReview:'inherit',externalReview:false};data.wb.delivery[ui.deliveryScope][key.slice(9)]=value;}else if(key==='database:write')wbConnection().write=value;else if(key.startsWith('db-access:')){const d=wbConnection(),pid=key.slice(10);d.access[pid]=value;if(value==='None')d.projects=d.projects.filter(p=>p!==pid);else if(!d.projects.includes(pid))d.projects.push(pid);}else data.wb.settings[key]=value;if(!key.startsWith('ui:'))wbAudit('settings.update','Updated '+key,String(value));persist();render();if(!key.startsWith('ui:'))toast('Setting saved · effective permissions remain enforced');}
