document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.card&&data.wb.issues.some(i=>i.id===d.card)){e.preventDefault();e.stopImmediatePropagation();wbActions.issue({id:d.card});return;}if(d.wb){e.preventDefault();e.stopImmediatePropagation();try{const result=wbActions[d.wb]?.(d);if(result?.catch)result.catch(error=>toast(error.message));if(!wbActions[d.wb])toast('This control has no preview yet.');}catch(error){toast(error.message);}return;}const replacements={settings:()=>wbActions.settings({}),usage:()=>wbPage('usage'),'repo-detail':()=>wbActions.repository(d),'open-review':()=>wbActions.approval(d),'new-knowledge':()=>wbEditKnowledge(),'edit-knowledge':()=>wbEditKnowledge(d.id),sessions:()=>wbAgentDialog('feature-coordinator'),'feature-sessions':()=>wbAgentDialog('feature-coordinator'),'merge-request':()=>{ui.repository=d.id;ui.repoTab='Reviews';wbPage('repository');}};if(replacements[d.x]){e.preventDefault();e.stopImmediatePropagation();replacements[d.x]();return;}if(d.x==='open-notification'){const n=data.notifications.find(x=>x.id===d.id);if(n?.completion){e.preventDefault();e.stopImmediatePropagation();rfOpenNotification(n.id);return;}if(n?.target==='approval'){e.preventDefault();e.stopImmediatePropagation();oldDispatch('notification.read',{id:n.id});wbActions.approval({id:n.ref});return;}}if((d.x==='toggle-run'||d.x==='feature-action')&&data.features.find(f=>f.id===d.id)?.approved===false){e.preventDefault();e.stopImmediatePropagation();wbActions['approve-plan'](d);}},true);
dispatch=function(command,args={},actor='You'){if(command==='tasks.prioritize')return wbPrioritizeTaskQueue(args,actor);if(command==='card.update'||command==='tasks.edit')return wbPatchProjectTask(args.id,args.version,args.patch,actor);if(command==='card.create'){const f=data.features.find(x=>x.id===args.feature);if(!f)throw Error('Choose a feature.');wbValidateTaskDependencies('new-task',f.project,args.deps||[]);}if(command==='feature.update'){const f=data.features.find(x=>x.id===args.id);assertVersion(f,args.version);if(args.patch.title!==undefined&&!args.patch.title.trim())throw Error('A feature title is required.');const patch={...args.patch},keys=['requirements','acceptance','repos'];if(f.approved&&keys.some(k=>k in patch&&JSON.stringify(patch[k])!==JSON.stringify(f[k]))){const draft={...Object.fromEntries(keys.map(k=>[k,f.pendingPlan?.[k]??f[k]])),...Object.fromEntries(keys.filter(k=>k in patch).map(k=>[k,patch[k]]))};f.pendingPlan={...draft,revision:f.version+1,state:'Draft'};for(const k of keys)delete patch[k];wbAudit('plan.draft','Saved pending plan revision',f.id,{feature:f.id});}args={...args,patch};}if(command==='run.toggle'){const f=data.features.find(x=>x.id===args.id);if(data.projects.find(p=>p.id===f?.project)?.archived)throw Error('Restore the archived project before starting work.');if(f?.run!=='Working'&&!f?.approved)throw Error('Plan approval is required before feature execution.');if(f?.run!=='Working'&&f?.budgetEnabled&&f.spent>=f.budgetAmount)throw Error('Feature budget reached. Increase or disable the limit, then Continue manually.');}const result=oldDispatch(command,args,actor);if(command==='run.redirect'){const scope='feature:'+args.feature,m=data.messages.at(-1);m.attachments=wbConsumeAttachments(scope);persist();}return result;};
function wbDecideFeaturePlan(d,approve){const f=data.features.find(x=>x.id===d.id);if(!f||String(f.pendingPlan?.revision||0)!==String(d.pending)||!f.pendingPlan&&String(f.version)!==String(d.edit))throw Error('The plan changed. Review the current pending revision before deciding.');if(approve){if(f.pendingPlan){for(const k of ['requirements','acceptance','repos'])f[k]=f.pendingPlan[k];delete f.pendingPlan;}f.approved=true;}else{if(!f.pendingPlan)throw Error('There is no pending revision.');f.pendingPlan.state='Rejected';}f.version++;wbAudit(approve?'plan.approve':'plan.reject',approve?'Approved feature plan':'Rejected pending plan revision',f.id,{feature:f.id});closeDialog();render();toast(approve?'Plan approved · existing execution controls preserved':'Revision rejected · approved plan remains active');}
