function wbBind(){wbBindComposers();const wi=$('#workspace-chat-draft');if(wi){const update=()=>{const send=$('#workspace-chat-form [type=submit]');if(send)send.disabled=!wi.value.trim()&&!wbPending('workspace:'+workspaceConversation().id).length;};wi.addEventListener('input',update);update();}const ff=$('#coordinator-form');if(ff)ff.addEventListener('submit',()=>{const input=$('#coordinator-draft');if(!input.value.trim()&&wbPending('feature:'+feature().id).length)input.value='Please inspect the attached files.';},true);for(const [input,key]of [['wb-knowledge-search','knowledgeSearch'],['wb-issue-search','issueQuery'],['wb-artifact-search','artifactQuery'],['wb-tool-search','toolQuery']]){const el=document.getElementById(input);if(el)el.oninput=()=>{ui[key]=el.value;render();};}for(const el of $$('[data-config]'))el.id||='config-'+el.dataset.config.replace(/[^a-zA-Z0-9-]/g,'-');const f=$('#issue-chat-form');if(f){const input=$('#issue-chat-draft');input.oninput=()=>{wbIssue().draft=input.value;persist();};f.onsubmit=e=>{e.preventDefault();const x=wbIssue(),text=input.value.trim();if(!text&&!wbPending('issue:'+x.id).length)return;x.messages.push({role:'You',text,time:stamp(),attachments:wbConsumeAttachments('issue:'+x.id)});x.messages.push({role:x.coordinator,text:'Acknowledged. I will reconcile this direction at the next safe step; unrelated work continues.',time:stamp()});x.draft='';wbAudit('issues.redirect','Redirected '+x.id,text,{issue:x.id});render();};input.onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();f.requestSubmit();}};}}
