function vdKnowledgeTabs(){return `<nav class="wb-subnav vd-knowledge-tabs" aria-label="Knowledge views">${['Entries','Documents'].map(t=>`<button data-wb="knowledge-view" data-tab="${t}" class="${ui.knowledgeView===t?'active':''}">${t}</button>`).join('')}<span class="spacer"></span>${wbButton('Document settings','settings','data-topic="Knowledge"')}</nav>`;}
function vdDocuments(){
 const docs=data.wb.documents.filter(d=>(d.project===ui.project||d.shares.includes(ui.project))&&(ui.documentFilter==='All states'||d.status===ui.documentFilter)&&(d.name+' '+d.tags.join(' ')).toLowerCase().includes(ui.documentQuery.toLowerCase())),d=docs.find(x=>x.id===ui.document)||docs[0];
 return pageHeader('Knowledge documents','Documents and source passages for '+project().name+'.',wbButton('Import documents','document-import','',true))+`<section class="rf-collection rf-document-collection">${vdKnowledgeTabs()}<div class="rf-collection-toolbar vd-document-toolbar"><input id="vd-document-query" class="wb-search" type="search" placeholder="Find documents or tags…" aria-label="Find documents" value="${esc(ui.documentQuery)}">${wbSelect('ui:documentFilter',['All states','Indexed','Partial','Failed','Not indexed','Awaiting extraction'],ui.documentFilter,'Document indexing state')}<span class="wb-small">${docs.length} documents</span>${wbButton('Search passages','document-search')}</div><div class="vd-drop-hint" id="vd-document-drop" tabindex="0" role="button" aria-label="Import documents by dropping files or pressing Enter">${icon('file')} Drop Markdown, text, PDF or Word documents</div><div class="rf-split-layout vd-document-layout"><div class="wb-list rf-master-list">${rfMasterHeading('Documents',docs.length)}${docs.map(x=>`<button class="${x.id===d?.id?'selected':''}" data-wb="document-select" data-id="${x.id}"><small>${esc(x.format)} · ${esc(x.status)}</small><strong>${esc(x.name)}</strong><small>${x.chunks} chunks · ${esc(rfProjectName(x.project))}${x.shares.length?' · shared':''}${x.enabled?'':' · retrieval disabled'}</small></button>`).join('')||'<div class="wb-empty">No documents match this project and filter.</div>'}</div><article class="wb-detail rf-detail-pane">${d?vdDocumentDetail(d):'<div class="wb-empty">Import a document to build this project’s library.</div>'}</article></div></section>`;
}

function vdDocumentDetail(d){return `<div class="wb-flex">${wbChip(d.status,d.status==='Indexed'?'green':d.status==='Partial'?'amber':'')}${wbChip(d.format)}${wbChip('Managed project artifact')}${wbChip('r'+d.revision)}</div><h2>${esc(d.name)}</h2><div class="wb-flex">${wbButton('Open managed file','artifact',`data-id="${d.artifact}"`)}${wbButton('Share / move','document-scope',`data-id="${d.id}"`)}${wbButton(d.enabled?'Disable retrieval':'Enable retrieval','document-toggle',`data-id="${d.id}"`)}</div><nav class="wb-subnav vd-detail-tabs">${['Overview','Passages','Index history'].map(t=>`<button data-wb="document-tab" data-tab="${t}" class="${ui.documentTab===t?'active':''}">${t}</button>`).join('')}</nav>${ui.documentTab==='Passages'?d.passages.map((p,i)=>`<section class="vd-passage"><div class="wb-between"><b>${esc(p.locator)}</b>${wbButton('Open citation','document-citation',`data-id="${d.id}" data-index="${i}"`)}</div><p>${esc(p.text)}</p><small>r${d.revision} · chunk ${i+1} · ${esc(d.hash)}</small></section>`).join('')||'<div class="wb-empty">No passages published. Inspect the extraction failure or pending indexing attempt.</div>':ui.documentTab==='Index history'?`${d.runs.map(r=>`<div class="vd-pipeline-run"><div class="wb-between"><strong>${esc(r.state)}</strong><span>${esc(r.time)}</span></div><p>${esc(r.text)}</p></div>`).join('')}<div class="wb-note wb-gap">Each attempt keeps its outcome. Cached extraction is reused for unchanged pages; re-extraction and embeddings are separate stages.</div>`:`<dl class="metadata-grid vd-doc-metadata"><div><dt>Project</dt><dd>${esc(data.projects.find(p=>p.id===d.project)?.name)}</dd></div><div><dt>Explicit sharing</dt><dd>${d.shares.map(p=>esc(data.projects.find(x=>x.id===p)?.name)).join(', ')||'Project only'}</dd></div><div><dt>Source</dt><dd>${esc(d.source)}</dd></div><div><dt>Retained copy</dt><dd>Project artifact · ${esc(d.artifact)}</dd></div><div><dt>Extraction</dt><dd>${esc(d.extraction)}</dd></div><div><dt>Embedding</dt><dd>${esc(d.embedding)}</dd></div><div><dt>Indexed</dt><dd>${esc(d.indexed)}</dd></div><div><dt>Content revision</dt><dd class="wb-mono">r${d.revision} · ${esc(d.hash)}</dd></div></dl><div class="wb-tags">${d.tags.map(t=>wbChip(t)).join('')}${d.feature?`<button class="wb-chip" data-feature="${d.feature}">${d.feature}</button>`:''}${d.task?`<button class="wb-chip" data-card="${d.task}">${d.task}</button>`:''}</div><div class="vd-pipeline"><span class="done">Extract</span><i>→</i><span class="${d.chunks?'done':''}">Chunk</span><i>→</i><span class="${d.chunks?'done':''}">Embed via router</span><i>→</i><span class="${d.status==='Indexed'?'done':''}">Publish</span></div>${d.status!=='Indexed'?`<div class="wb-note attention">${esc(d.runs[0]?.text||'Awaiting indexing')}</div>`:''}<div class="wb-note">The managed copy remains available if the original is moved or deleted. Removing its search index preserves the file and original provenance.</div><div class="button-group">${wbButton('Preview reindex','document-reindex',`data-id="${d.id}"`)}${wbButton('Indexing logs','document-logs',`data-id="${d.id}"`)}${wbButton('Remove index…','document-remove-index',`data-id="${d.id}"`)}</div>`}`;}
function vdPassageSearch(){showDialog('Search document passages',`<form id="vd-passage-form"><label for="vd-passage-input" class="wb-small">Search within ${esc(project().name)} and explicitly shared documents</label><div class="wb-toolbar wb-gap"><input class="wb-search" id="vd-passage-input" type="search" value="${esc(ui.documentSearch)}" placeholder="Try import, recovery or navigation…"><button class="btn primary" type="submit">Search</button></div></form><div class="wb-note">Local sample passage search uses text matching. Production retrieval will combine lexical and vector search through configured routes; no inference runs here.</div><div id="vd-passage-results"></div>`);const run=()=>{ui.documentSearch=$('#vd-passage-input').value;const q=ui.documentSearch.toLowerCase().trim(),hits=data.wb.documents.filter(d=>d.enabled&&(d.project===ui.project||d.shares.includes(ui.project))).flatMap(d=>d.passages.map((p,i)=>({d,p,i}))).filter(x=>q&&x.p.text.toLowerCase().includes(q));$('#vd-passage-results').innerHTML=hits.map(({d,p,i})=>`<section class="vd-passage"><button class="wb-link" data-wb="document-citation" data-id="${d.id}" data-index="${i}">${esc(d.name)} · ${esc(p.locator)}</button><p>${esc(p.text)}</p><small>r${d.revision} · source evidence · lexical match</small></section>`).join('')||`<div class="wb-empty">${q?'No matching passages. Try another term; no answer has been invented.':'Enter a term to inspect source passages.'}</div>`;persist();};$('#vd-passage-form').onsubmit=e=>{e.preventDefault();run();};run();}
async function vdImportDocuments(files){
 const supported=/\.(md|markdown|txt|pdf|docx|doc)$/i;let count=0,rejected=[];
 for(const f of files){if(!supported.test(f.name)){rejected.push(f.name);continue;}const aid=id('doc');await wbPutBlob(aid,f);const format=/\.pdf$/i.test(f.name)?'PDF':/\.docx?$/i.test(f.name)?'Word':/\.md|\.markdown$/i.test(f.name)?'Markdown':'Plain text';const text=['Markdown','Plain text'].includes(format)?await f.text():'';const d={id:aid,artifact:aid,project:ui.project,shares:[],name:f.name,format,status:'Awaiting extraction',enabled:true,revision:1,hash:'Managed import · hash pending',chunks:0,pages:0,tags:[],created:'Just now',indexed:'Not indexed',embedding:'Not run',extraction:'Queued · no model invoked in this UI study',source:'Imported file · '+f.name,passages:[],runs:[{time:stamp(),state:'Awaiting extraction',text:'Managed file copied. Extraction, chunking and embeddings await the production indexing pipeline.'}]};data.wb.documents.unshift(d);data.wb.artifacts.push({id:aid,name:f.name,project:ui.project,shares:[],kind:'Knowledge document',agent:'You',created:'Just now',size:Math.ceil(f.size/1024)+' KB',blob:true,managed:true,mime:f.type,text});ui.document=d.id;count++;}
 wbAudit('documents.import','Imported managed knowledge documents',count+' files; no provider calls');ui.knowledgeView='Documents';ui.page='knowledge';ui.documentQuery='';ui.documentFilter='All states';render();toast(count+' imported'+(rejected.length?' · unsupported: '+rejected.join(', '):' · originals are independent'));
}
function vdOpenImport(){const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='.md,.markdown,.txt,.pdf,.doc,.docx';input.onchange=()=>vdImportDocuments([...input.files]).catch(e=>toast(e.message));input.click();}
function vdDocumentScope(did){const d=data.wb.documents.find(x=>x.id===did);showDialog('Share or move · '+d.name,`<div class="form-grid">${choose('project','Owning project',data.projects.filter(p=>!p.archived).map(p=>[p.id,p.name]),d.project)}</div><h3 class="wb-gap">Also share with</h3><div class="vd-checklist">${data.projects.filter(p=>!p.archived).map(p=>`<label><input type="checkbox" name="share" value="${p.id}" ${d.shares.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div><p class="help">Moving preserves identity, managed bytes and history. The former project retains future access only if explicitly shared. Existing transcript evidence is preserved.</p>`,fd=>{const before={project:d.project,shares:[...d.shares]};d.project=fd.get('project');d.shares=fd.getAll('share').filter(p=>p!==d.project);const a=data.wb.artifacts.find(x=>x.id===d.artifact);a.project=d.project;a.shares=[...d.shares];wbAudit('documents.scope','Updated document scope',JSON.stringify({document:d.id,before,after:{project:d.project,shares:d.shares}}));});}
function vdAddons(){const list=data.wb.addons.filter(a=>(ui.addonFilter==='All add-ons'||a.kind===ui.addonFilter)&&(a.name+' '+a.contributions).toLowerCase().includes(ui.addonQuery.toLowerCase()));return `${wbHeading('Add-ons','Optional language semantics and independent harness extensions. Compatible prebuilt executables install without rebuilding DevWorks.','','Workspace settings')}<div class="wb-toolbar"><input id="vd-addon-query" class="wb-search" type="search" value="${esc(ui.addonQuery)}" placeholder="Find add-ons or contributions…" aria-label="Find add-ons">${wbSelect('ui:addonFilter',['All add-ons','Language pack','Harness extension'],ui.addonFilter,'Filter add-ons')}${wbButton('Install local package…','addon-install','',true)}</div>${wbPanel('Installed & available packages',wbTable(['Package','Version / state','Contributions',''],list.map(a=>`<tr><td><button class="wb-link" data-wb="addon-detail" data-id="${a.id}">${esc(a.name)}</button><small>${esc(a.kind)} · ${esc(a.source)}</small></td><td>${esc(a.version)}<small>${wbChip(a.state,a.state==='Enabled'?'green':a.state==='Awaiting approval'?'amber':'')}</small></td><td class="vd-wrap">${esc(a.contributions)}</td><td>${wbButton(a.state==='Available'?'Install…':'Manage','addon-detail',`data-id="${a.id}"`)}</td></tr>`)))}${wbPanel('Baseline & permissions',wbSetting('Tree-sitter parsing','Built in across supported grammars. Disabling a semantic pack leaves structural indexing available.',wbChip('Always available','green'))+wbSetting('Agent-authored changes','Review exact version, contents, access and evidence before activation. Existing versions stay active until approval.',wbButton('Approval queue','go','data-page-target="reviews"'))+wbSetting('Extension UI & inference','Host-defined native egui panels; provider extensions and inference use the shared router.',wbButton('How to build a package','help','data-topic="plugins"')))}<div class="wb-note">Pack versions and installation states are samples. Prerequisites are checked per platform in the production app; this screen installs no executables or toolchains.</div>`;}
