 'project-archive':d=>{const p=data.projects.find(x=>x.id===d.id),active=[...data.features,...data.wb.issues].filter(x=>x.project===p.id&&x.run==='Working'),jobs=data.wb.jobs.filter(j=>j.scope===p.name&&j.state==='Running');showDialog('Archive '+p.name+'?',`<div class="wb-note ${active.length||jobs.length?'attention':''}">${active.length} active work coordinators · ${jobs.length} active scheduled runs</div><p class="wb-small">${active.length||jobs.length?'Confirming stops all project work immediately; it does not wait for a safe step.':'Project work and schedules will stay stopped.'} History is preserved.</p><div class="button-group wb-gap">${wbButton('Archive & stop now','project-archive-confirm',`data-id="${p.id}"`)}${wbButton('Cancel','project-cancel')}</div>`);},
