function vdDeleteProject(pid){if(data.projects.length<2)throw Error('Keep at least one sample project.');const p=data.projects.find(x=>x.id===pid),fids=data.features.filter(f=>f.project===pid).map(f=>f.id);data.features=data.features.filter(f=>f.project!==pid);data.cards=data.cards.filter(c=>!fids.includes(c.feature));data.messages=data.messages.filter(m=>!fids.includes(m.feature));data.knowledge=data.knowledge.filter(k=>k.project!==pid||k.scope==='Shared');data.wb.issues=data.wb.issues.filter(x=>x.project!==pid);data.wb.documents=data.wb.documents.filter(d=>{d.shares=d.shares.filter(x=>x!==pid);if(d.project!==pid)return true;if(d.shares.length){d.project=d.shares.shift();return true;}return false;});data.wb.artifacts=data.wb.artifacts.filter(a=>{a.shares=(a.shares||[]).filter(x=>x!==pid);if(a.project!==pid)return true;if(a.shares.length){a.project=a.shares.shift();return true;}return false;});data.wb.jobs=data.wb.jobs.filter(j=>j.scope!==p.name);data.wb.conventions=data.wb.conventions.filter(c=>c.project!==pid);data.reviews=data.reviews.filter(r=>r.project!==pid);data.claims=data.claims.filter(c=>c.project!==pid);for(const db of data.wb.databases){db.projects=db.projects.filter(x=>x!==pid);delete db.access[pid];}delete data.wb.projectConfig[pid];delete data.wb.workflows[pid];data.wb.approvals=data.wb.approvals.filter(a=>a.project!==pid);data.events=data.events.filter(e=>e.project!==pid);data.notifications=data.notifications.filter(n=>n.project!==pid);data.projects=data.projects.filter(x=>x.id!==pid);ui.project=data.projects[0].id;ui.page='portfolio';persist();}
