const vdBindBase=wbBind;wbBind=function(){vdBindBase();for(const [id,key]of [['vd-document-query','documentQuery'],['vd-help-query','helpQuery'],['vd-addon-query','addonQuery']]){const e=document.getElementById(id);if(e)e.oninput=()=>{ui[key]=e.value;render();};}const sq=$('#vd-settings-query');if(sq){const filter=()=>{ui.settingsQuery=sq.value;for(const b of $$('.wb-settings-nav [data-tab]'))b.hidden=!(b.textContent+' '+vdSettingsSummary(b.dataset.tab).join(' ')).toLowerCase().includes(sq.value.toLowerCase());persist();};sq.oninput=filter;filter();}const drop=$('#vd-document-drop');if(drop){drop.onclick=vdOpenImport;drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();vdOpenImport();}};drop.ondragover=e=>{e.preventDefault();drop.classList.add('wb-dragover');};drop.ondragleave=()=>drop.classList.remove('wb-dragover');drop.ondrop=e=>{e.preventDefault();vdImportDocuments([...e.dataTransfer.files]).catch(e=>toast(e.message));};}};
