function vdEffectiveChoice(scope,key){let v=data.wb.settings[key],source='workspace';const pid=scope.startsWith('project:')?scope.slice(8):data.projects.find(p=>p.repos.includes(scope))?.id;for(const id of [pid?'project:'+pid:null,scope==='Workspace'||scope.startsWith('project:')?null:scope]){const x=id&&data.wb.delivery[id]?.[key];if(x&&x!=='inherit'){v=x;source=id;}}return ({ask:'Ask me',auto:'Automatic',off:'Disabled',on:'On'}[v]||v)+' · '+source;}
function vdGitHubOverrides(){const scope=ui.deliveryScope;return wbPanel('Project & repository overrides',`<div class="wb-panel-body"><label class="wb-small">Synchronization scope ${wbSelect('ui:deliveryScope',[['Workspace','Workspace defaults'],['project:'+ui.project,project().name+' project'],...project().repos.map(r=>[r,repo(r).name+' repository'])],scope,'GitHub synchronization policy scope')}</label></div>`+['importIssues','issueSync'].map(k=>wbSetting(k==='importIssues'?'Import open issues':'Synchronize linked issues',scope==='Workspace'?'On by default; inherited by projects and repositories.':('Effective: '+vdEffectiveBoolean(scope,k)),scope==='Workspace'?wbBool(k,data.wb.settings[k],k==='importIssues'?'Import open issues':'Synchronize linked issues'):wbSelect('delivery:'+k,[['inherit','Inherit'],['on','On'],['off','Off']],data.wb.delivery[scope]?.[k]||'inherit',k+' override'))).join(''));}
function vdEffectiveBoolean(scope,key){let v=data.wb.settings[key],source='workspace';const pid=scope.startsWith('project:')?scope.slice(8):data.projects.find(p=>p.repos.includes(scope))?.id;for(const id of [pid?'project:'+pid:null,scope.startsWith('project:')?null:scope]){const x=id&&data.wb.delivery[id]?.[key];if(x&&x!=='inherit'){v=x==='on';source=id;}}return (v?'On':'Off')+' · '+source;}
