const vdArtifactDelete=wbActions['artifact-delete'];wbActions['artifact-delete']=d=>{const a=data.wb.artifacts.find(x=>x.id===d.id);if(a?.shares?.length){showDialog('Remove artifact from this project',`<p class="wb-small">${esc(a.name)} is shared. Removing this project’s reference preserves the managed file for the other projects.</p><div class="wb-gap">${wbButton('Remove this project reference','artifact-remove-reference',`data-id="${a.id}"`)}</div>`);}else vdArtifactDelete(d);};
