function rfIntegratePage(main){
 if(ui.page==='chat'){$('.workspace-chat-layout>.workspace-chat')?.classList.add('rf-primary-pane');return;}
 const surface=main.querySelector('.dw-screen-content')||main,header=surface.querySelector('.rf-page-header');
 if(!header||header.closest('.rf-primary-pane'))return;
 const bodyFor=host=>{
  const body=document.createElement('div');body.className='rf-primary-scroll';
  for(const child of [...host.childNodes])body.append(child);
  host.append(body);return body;
 };
 const integrate=host=>{
  header.remove();const body=bodyFor(host);host.classList.add('rf-primary-pane');host.prepend(header);return body;
 };
 const contentChildren=()=>[...surface.children].filter(x=>x!==header&&!x.matches('.topbar,.rf-completion-shelf'));
 const settings=surface.querySelector('.wb-settings');
 if(settings){
  const primary=settings.querySelector('.wb-settings-content'),nav=settings.querySelector('.wb-settings-nav');
  integrate(primary);settings.classList.add('rf-integrated-layout','rf-settings-layout');nav.classList.add('rf-secondary-pane');return;
 }
 const featureFrame=surface.querySelector('.feature-frame');
 if(featureFrame){
  const primary=featureFrame.querySelector('.feature-left'),chat=featureFrame.querySelector('.run-chat');
  header.remove();primary.classList.add('rf-primary-pane');primary.prepend(header);
  let previous=header;for(const chrome of contentChildren().filter(x=>x!==featureFrame)){chrome.remove();previous.after(chrome);previous=chrome;}
  featureFrame.classList.add('rf-integrated-layout','rf-feature-layout');chat?.classList.add('rf-secondary-pane');return;
 }
 const split=surface.querySelector('.rf-split-layout,.rf-database-layout,.wb-detail-layout');
 if(split){
  const master=split.children[0],primary=split.children[1];
  if(!master||!primary)return;
  const collection=split.closest('.knowledge-shell,.rf-dream-collection,.rf-document-collection');
  const controls=collection?[...collection.children].filter(x=>x!==split):contentChildren().filter(x=>x!==split);
  const tabs=controls.filter(x=>x.matches('nav'));
  const tools=controls.filter(x=>!tabs.includes(x));
  integrate(primary);
  let previous=header;
  for(const tab of tabs){tab.classList.add('rf-integrated-tabs');previous.after(tab);previous=tab;}
  master.classList.add('rf-secondary-pane','rf-master-pane');
  if(!master.querySelector('.rf-master-heading'))master.insertAdjacentHTML('afterbegin',rfMasterHeading(({reviews:'Approvals',jobs:'Schedules',help:'Topics',indexing:'Attempts'})[ui.page]||'Browse',master.querySelectorAll(':scope>button').length));
  const masterHeading=master.querySelector('.rf-master-heading');
  previous=masterHeading;
  for(const tool of tools){tool.classList.add('rf-sidebar-tools');previous.after(tool);previous=tool;}
  split.classList.add('rf-integrated-layout','rf-master-detail-layout');
  if(['reviews','knowledge','dreaming','databases'].includes(ui.page)){split.classList.add('rf-sidebar-right');split.append(primary,master);}
  if(collection)collection.classList.add('rf-layout-host');
  return;
 }
 // Content pages retain their existing scrolling body and contextual sidebar.
 const originalScroll=header.parentElement.matches('.wb-scroll')?header.parentElement:null;
 header.remove();
 const nodes=contentChildren(),layout=document.createElement('div'),primary=document.createElement('section');
 layout.className='rf-integrated-layout';primary.className='rf-primary-pane';layout.append(primary);primary.append(header);
 const scroll=originalScroll||nodes.find(x=>x.matches('.wb-scroll,.body-scroll'));
 const summary=scroll?.querySelector(':scope>.rf-overview-summary');if(summary)primary.append(summary);
 const secondary=scroll?.querySelector('.wb-grid>aside,.project-grid>.project-aside');
 if(secondary){secondary.parentElement.classList.add('rf-primary-grid');secondary.classList.add('rf-secondary-pane','rf-context-pane');layout.classList.add('rf-with-context');layout.append(secondary);}
 if(scroll){
  for(const node of nodes)if(node!==scroll)primary.append(node);
  scroll.classList.add('rf-primary-scroll');primary.append(scroll);
 }else{
  const body=document.createElement('div');body.className='rf-primary-scroll rf-unstructured-body';
  for(const node of nodes){node.classList.add('rf-primary-content');body.append(node);}
  primary.append(body);
 }
 surface.append(layout);
}
